import * as React from "react"
import { cn } from "../../../src/lib/utils"

/**
 * Built from the Figma `Fasla Logo` set (41668:149234): the lockup in each
 * direction and the icon on its own, with the paths exported from Figma.
 *
 * - `lockup`, English: the red mark, then "fasla" (273×88).
 * - `lockup`, Arabic: the red mark on the right, where Arabic starts, then
 *   «فاصلة» (307×88).
 * - `icon`: the red mark alone (88×88), the same in both directions.
 *
 * The mark is brand artwork, so its red and white are written out; the
 * wordmark is `primary`, as Figma binds it, so it reads in dark mode too. The
 * logo never mirrors: the Arabic lockup is its own drawing.
 */

/** The red mark's brackets and comma, drawn in an 88×88 square whose start is `x`. */
function Mark({ x = 0 }: { x?: number }) {
  return (
    <g transform={x ? `translate(${x} 0)` : undefined}>
      <rect width="88" height="88" fill="#E40017" />
      <path d="M76 73H58V65H68V23H58V15H76V73Z" fill="white" />
      <path d="M30 23H20V65H30V73H12V15H30V23Z" fill="white" />
      <path d="M51 58H37V30L51 44V58Z" fill="white" />
    </g>
  )
}

