/** Where the Arabic lockup's mark starts: at its right end, after the wordmark. */
const RTL_MARK_X = 218.456

export interface FaslaLogoProps extends React.SVGProps<SVGSVGElement> {
  /** Figma `Logo Icon Only`: the full lockup, or the red mark alone. */
  variant?: "lockup" | "icon"
  /**
   * Figma `Direction`: the English lockup ("fasla") or the Arabic one
   * («فاصلة»). `auto` follows the page's `dir`. The icon is the same in both.
   */
  direction?: "auto" | "ltr" | "rtl"
  /** The accessible name. Pass "" when text beside the logo already names it. */
  title?: string
}

/**
 * The Fasla logo. It is 44px tall by default and keeps its proportions; set
 * the height with `className` (`h-6`, `h-8`). The wordmark is the text colour,
 * `primary` by default: on a dark band pass `text-foreground-inverse`.
 */
export function FaslaLogo({ variant = "lockup", direction = "auto", title = "Fasla", className, ...props }: FaslaLogoProps) {
  const svg = (dir: "ltr" | "rtl", extra?: string) => {
    const icon = variant === "icon"
    const width = icon ? 88 : dir === "rtl" ? 307 : 273
    return (
      <svg
        key={dir}
        xmlns="http://www.w3.org/2000/svg"
        viewBox={`0 0 ${width} 88`}
        fill="none"
        data-slot="fasla-logo"
        data-variant={variant}
        data-direction={dir}
        role={title ? "img" : undefined}
        aria-label={title || undefined}
        aria-hidden={title ? undefined : true}
        focusable="false"
        className={cn("h-11 w-auto shrink-0 text-primary", extra, className)}
        {...props}
      >
        {icon ? (
          <Mark />
        ) : dir === "rtl" ? (
          <>
            <Mark x={RTL_MARK_X} />
            <path d={RTL_WORDMARK} fill="currentColor" />
          </>
        ) : (
          <>
            <Mark />
            <path d={LTR_WORDMARK} fill="currentColor" />
          </>
        )}
      </svg>
    )
  }
  if (variant === "icon" || direction === "ltr") return svg("ltr")
  if (direction === "rtl") return svg("rtl")
  // `auto`: both drawings, one shown by the nearest `dir` above.
  return (
    <>
      {svg("ltr", "rtl:hidden")}
      {svg("rtl", "hidden rtl:block")}
    </>
  )
}
